import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { SupabaseClient } from '@supabase/supabase-js';
import { repo } from '../repo';

vi.mock('@supabase/supabase-js');

const mockClient = vi.mocked(SupabaseClient);

describe('appendChangeLog', () => {
  beforeEach(() => {
    mockClient.from.mockReturnValue({
      insert: vi.fn()
    });
  });

  it('should omit id from insert payload', async () => {
    const data = { action: 'test', table: 'test', record: {} };
    await repo.appendChangeLog(data);
    expect(mockClient.from).toHaveBeenCalledWith('changelog');
    expect(mockClient.from('changelog').insert).toHaveBeenCalledWith({
      action: 'test',
      table: 'test',
      record: {}
    });
  });

  it('should use snake_case for columns', async () => {
    const data = { action: 'test', table: 'test', record: {} };
    await repo.appendChangeLog(data);
    expect(mockClient.from('changelog').insert).toHaveBeenCalledWith({
      action: 'test',
      table: 'test',
      record: {}
    });
  });

  it('should propagate insert errors', async () => {
    const error = new Error('Insert failed');
    mockClient.from('changelog').insert.mockRejectedValue(error);
    await expect(repo.appendChangeLog({})).rejects.toThrow(error);
  });
});

